def after():
    joined = trips.join(taxi_zones, trips.pickup_zone_id == taxi_zones.zone_id)
    return joined.filter(F.col("borough") == "Old Quarter").select("trip_id", "zone_name", "total")


def before():
    old_quarter = taxi_zones.filter(F.col("borough") == "Old Quarter")
    joined = trips.join(old_quarter, trips.pickup_zone_id == old_quarter.zone_id)
    return joined.select("trip_id", "zone_name", "total")


print("same rows:", sorted(after().collect()) == sorted(before().collect()))
after_steps, before_steps = profile(after()), profile(before())
print("same profile:", after_steps == before_steps)
for step, counts in before_steps:
    print(step, counts)

